target.css:
:root {
  --paper: #fffdf8;
  --ink: #25323d;
  --coral: #e76951;
}

.guide-card {
  width: 460px;
  box-sizing: border-box;
  overflow: hidden;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 16px;
}

.guide-card header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
}

.guide-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  background: var(--coral);
  border-radius: 12px;
  font-size: 21px;
}

.guide-copy {
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--coral);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.guide-copy h1 {
  margin: 0;
  color: var(--ink);
  font-size: 20px;
  line-height: 1.1;
}

.duration {
  padding: 5px 8px;
  color: var(--ink);
  border: 1px solid var(--ink);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.guide-card footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--ink);
}

.guide-card footer p {
  margin: 0;
  color: var(--paper);
  font-size: 14px;
  font-weight: 600;
}

.guide-card button {
  padding: 7px 10px;
  color: var(--ink);
  background: var(--coral);
  border: 0;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 800;
}

.guide-card button span {
  margin-left: 4px;
}

